import{_ as i,o as e,c as t,a3 as a}from"./chunks/framework.D8u9WiMi.js";const g=JSON.parse('{"title":"十号的流水账","description":"","frontmatter":{},"headers":[],"relativePath":"listOfEvents/2026/march/10.md","filePath":"listOfEvents/2026/march/10.md"}'),o={name:"listOfEvents/2026/march/10.md"};function r(n,l,s,m,c,d){return e(),t("div",null,[...l[0]||(l[0]=[a('<h1 id="十号的流水账" tabindex="-1">十号的流水账 <a class="header-anchor" href="#十号的流水账" aria-label="Permalink to &quot;十号的流水账&quot;">​</a></h1><ol><li>Math类：进行基本的数学运算 <ol><li>abs 取整</li><li>ceil 小数向上取整，返回的类型还是小数（2.0)</li><li>floor 小数向下取整，返回的类型还是小数(2.0)</li><li>round 四舍五入 return int</li><li>max 对比返回大的</li><li>min 对比返回小的</li><li>pow 指定数的几次幂计算2^3</li><li>random 返回一个[0,1)的随机数</li></ol></li><li>System类：包含操作系统的一些常用方法 <ol><li>currentTimeMillis() 获取当前时间对应的时间戳，可以用来计算代码执行了多久</li><li>exit 终止jvm虚拟机(0)表示终止的状态，是正常退出</li><li>arraycopy 复制a数组中从指定索引开始的值，到b数组的指定索引</li></ol></li><li>Runtime 表示java虚拟机的运行时对象，可以获取程序运行信息 <ol><li>getRuntime 获取虚拟机对象实例</li><li>exit 停止虚拟机</li><li>availableProcessors 获取当前设备的cpu线程数</li><li>maxMemory jvm能从系统中获取的最大内存数，单位比特(byte)</li><li>totalMemory jvm已经从系统中分配到的最大内存数</li><li>freeMemory 已经从系统中分配的内存中，剩余没使用的部分</li><li>exec 运行cmd命令</li></ol></li><li>Object（重点）Object类是所有类的根类 <ol><li>toString 返回对象的字符串表现形式，输出的就是指向对象存储内存的地址的哈希字符串</li><li>equals(Object obj) 比较两个值是否相等，如果是引用数据类型其实对比的是地址了</li><li>clone 拷贝对象---其实是浅拷贝 <ol><li>深拷贝可以用gson.toJson() 再fromJson就可以，和js差不多</li></ol></li></ol></li><li>Objects类：主要用来操作对象 <ol><li>equals 先做非空判断，比较两个对象</li><li>isNull判断是否为空</li><li>nonNull 如果提供的引用为非<code>null</code>则返回<code>true</code>，否则返回<code>false</code>。</li></ol></li><li>BigInteger 再int取值范围不够用时使用 <ol><li>BigInteger add 加</li><li>BigInteger subtract 减</li><li>BigInteger multiply 乘</li><li>BigInteger divide 除</li><li>BigInteger[] divideAndRemainder 除，同时获取商和余数</li><li>equals 比较是否相同</li><li>pow 次方</li><li>max/min 比较返回较大/较小值</li></ol></li><li>BigDecimal类 主要是解决浮点数计算的精度问题 <ol><li>0.09+0.01=0.09999999999999999999</li><li>valueOf 获取BigDecimal对象</li><li>add 加法</li><li>subtract 减法</li><li>multiply 乘法</li><li>divide 除法</li></ol></li><li>SimpleDateFormat类 是日期/时间格式化类，可以实现Date对象和String对象的转换 JAVA7的 <ol><li>y M d H m s 年月日时分秒</li><li>String format(Date date); 将Date对象格式化为字符串</li><li>Date prase(String source); 将字符串解析为Date对象</li></ol></li><li>Calendar类（重点）是个日历类，而且是个抽象类，不能创建对象，用来做日历的计算很好用，一般用它的子类 <ol><li>GregorianCalendar类</li><li>getInstance 获取实例对象</li><li>getTime 是获取时间戳</li><li>get获取指定信息的，传递的是自己的常量</li><li>Calendar.YEAY 获取日历对象的年份</li><li>Calendar.MONTH</li><li>Calender.DAY_OF_MONTH 当前月份的第几天</li><li>add日期计算</li><li>Calendar.getInstance().getTime();calendar转换为date格式</li></ol></li><li>ZoneId时区 表示时区的类。可以偏移计算，可以获取对应的时区信息</li><li>Instant 时间戳类 <ol><li>判断什么时候在什么时间的前面还是后面比较好用</li></ol></li><li>ZonedDateTime 带时区的时间</li><li>DateTimeFormatter 用于时间的格式化和解析 <ol><li>ofPattern 获取指定格式的格式化实例对象</li><li>format 按照指定方式格式化</li></ol></li><li>LoclDateTime处理本地日期时间 <ol><li>他的两个子类分别是LocalDate和LocalTime</li><li>都是线程安全的，可以在多线程环境中使用。</li><li>.now()获取当前日历时间</li><li>of(2023,1,1)获取指定的日期对象</li><li>getYear ....能获取当月的第几天和当年的第几天</li><li>isbefore和isAfter 可以判断日期是否在指定日期的前或后</li><li>with修改日期，只能修改年月日</li><li>minus减少，只能修改年月日</li></ol></li></ol><blockquote><p>晚上想吃新疆手抓饭呢，去了之后手抓饭就只剩两种了，羊里脊和羊排，在店里点就有点贵了,所以没买。</p><p>想再看看别的吃的呢，给王耀打电话想看看他吃的啥，他找了个小火锅自助，又被他说服了，去吃小火锅自助了，哎原本原本觉得二十七八的手抓饭有点贵，结果吃了个更贵的，晚饭少吃的目标又打破了，而起吃自助就会不自主的猛吃。看看还有没有机会运动运动吧，小火锅还不错，性价比很高，竟然才35.9每人。</p><p>而且更完蛋的是，我只要晚上吃的很好，自助，火锅，烧烤，或者喝酒了，那么回来就只想打游戏了。继续颓废的一天。</p><p>战意这破游戏也够恶心的，赛季任务太难做了，想弄个大剑玩玩，还得兵团400分，tm的怎么打啊，而起我不想玩别的，什么工会任务，出城剿匪，对我来说就是垃圾时间，就不能让我开开心心的玩排行或攻城就把任务做了吗，干！游戏玩的很生气。就这样</p></blockquote>',3)])])}const p=i(o,[["render",r]]);export{g as __pageData,p as default};
